public class Main {

    static List<Integer> stuckStudents(int n, int[][] waits) {

        // graph[b] = students who are waiting for b
        List<List<Integer>> graph = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // in[a] = number of students that a is still waiting for
        int[] in = new int[n];

        for (int[] edge : waits) {
            int a = edge[0];
            int b = edge[1];

            // a waits for b
            // When b finishes, a gets one dependency resolved.
            graph.get(b).add(a);
            in[a]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();

        // These students wait for nobody,
        // so they finish immediately.
        for (int i = 0; i < n; i++) {
            if (in[i] == 0) {
                queue.offer(i);
            }
        }

        boolean[] finished = new boolean[n];

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            finished[curr] = true;

            // curr has finished.
            // Every student waiting for curr has
            // one fewer unfinished dependency.
            for (int next : graph.get(curr)) {
                in[next]--;

                if (in[next] == 0) {
                    queue.offer(next);
                }
            }
        }

        // Anyone not processed can never finish.
        List<Integer> ans = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (!finished[i]) {
                ans.add(i);
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {

        BufferedReader br =
                new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] waits = new int[m][2];

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());

            waits[i][0] = Integer.parseInt(st.nextToken()) - 1;
            waits[i][1] = Integer.parseInt(st.nextToken()) - 1;
        }

        List<Integer> stuck = stuckStudents(n, waits);

        System.out.println(stuck.size());

        if (!stuck.isEmpty()) {
            StringBuilder sb = new StringBuilder();

            for (int student : stuck) {
                sb.append(student + 1).append(" ");
            }

            System.out.println(sb);
        }
    }
}

