        int n = hours.length;
        long[][] dp = new long[n + 1][H+1];

        for(int i = 0; i <= n; i++) {
            dp[i][0] = 0;
        }
        for(int i = 0; i <= H; i++) {
            dp[0][i] = 0;
        }
        for(int i = 1; i <= n; i++) {
